#include "stdafx.h"#include "H_Class.h"static SBlockCreate _2OO3( "2OO3", SH_2OO3::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_2OO3,W_2OO3,11)void SH_2OO3::InitParm(){#include "Blocks/2OO3.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/2OO3_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class _2OO3_IMPL : public W_2OO3{public:  void StepT( SStepCalcParams &dt, int inConsC );};void SH_2OO3::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  _2OO3_IMPL *impl = reinterpret_cast<_2OO3_IMPL*>(W);  impl->StepT( dt, inConsC );  OutputConnectionsTransfer();}//////////////////////////////////////////////////////////////////////////void _2OO3_IMPL::StepT( SStepCalcParams &dt, int inConsC ){  int k = 0;  if( IN[1] )    k++;  if( IN[2] )    k++;  if( IN[3] )    k++;  if ( k >= 2 )    MAJ = true;  else    MAJ = false;}